// The mod's type contract. `claude plugin validate` checks every `$.state`
// value the hooks module names against `PluginState` below, and the hooks
// module imports these types from '../types'.

/** Where a checklist item came from: Claude's task list, a /manual or MANUAL: step, or a loose end surfaced from the conversation. */
export type ItemSource = 'todo' | 'manual' | 'followup'

/** The same three states TodoWrite uses. */
export type ItemStatus = 'pending' | 'in_progress' | 'completed'

/** One line of this session's checklist. */
export type ChecklistItem = {
  /** Short number shown in the pane and typed after /done. Stable for the session. */
  id: number
  text: string
  source: ItemSource
  status: ItemStatus
  /** True once the person ticked it themselves. A ticked item stays done. */
  ticked: boolean
  /** The id Claude Code gave the task, for items that came from TaskCreate. */
  taskId?: string
}

/** The checklist plus the counter that hands out ids. */
export type Checklist = {
  items: ChecklistItem[]
  nextId: number
}

/** What one session writes to ~/.claude/board/<session-id>.json. */
export type BoardSession = {
  sessionId: string
  project: string
  cwd: string
  /** One sentence on what the session is handling right now. */
  summary: string
  items: ChecklistItem[]
  /** ISO 8601 time of the last write. */
  updatedAt: string
  /** ISO 8601 time the session ended, once it has. */
  endedAt?: string
  /** Where the session runs: a short host name, or "cloud". */
  machine?: string
  /** The terminal the session runs in, such as /dev/ttys003, when it has one. */
  tty?: string
  /** Where a cloud session opens in a browser or the Desktop app: its claude.ai/code page. */
  url?: string
}

declare module 'claude-code' {
  interface PluginState {
    'cc-board': {
      checklist: Checklist
      summary: string
      board: BoardSession[]
    }
  }
}
